export const unsaveMessage = <ThrowOnError extends boolean = false>(options: Options<UnsaveMessageData, ThrowOnError>): RequestResult<UnsaveMessageResponses, UnsaveMessageErrors, ThrowOnError> => (options.client ?? client).delete<UnsaveMessageResponses, UnsaveMessageErrors, ThrowOnError>({ url: '/api/messages/{id}/saved', ...options });

/**
 * Save a message or reply for the acting member (a message.saved event). Saving it again changes nothing.
 */
export const saveMessage = <ThrowOnError extends boolean = false>(options: Options<SaveMessageData, ThrowOnError>): RequestResult<SaveMessageResponses, SaveMessageErrors, ThrowOnError> => (options.client ?? client).put<SaveMessageResponses, SaveMessageErrors, ThrowOnError>({ url: '/api/messages/{id}/saved', ...options });

/**
 * The acting member's unsent drafts, newest first: one per channel message box or thread reply box
 */
export const listDrafts = <ThrowOnError extends boolean = false>(options?: Options<ListDraftsData, ThrowOnError>): RequestResult<ListDraftsResponses, ListDraftsErrors, ThrowOnError> => (options?.client ?? client).get<ListDraftsResponses, ListDraftsErrors, ThrowOnError>({ url: '/api/me/drafts', ...options });

/**
 * Keep the text typed in a channel's message box or a thread's reply box, so it follows the member to another device. It replaces the earlier draft there; empty text clears it. Sending the message clears it too. A draft is current state, not an event.
 */
export const saveDraft = <ThrowOnError extends boolean = false>(options: Options<SaveDraftData, ThrowOnError>): RequestResult<SaveDraftResponses, SaveDraftErrors, ThrowOnError> => (options.client ?? client).put<SaveDraftResponses, SaveDraftErrors, ThrowOnError>({
    url: '/api/me/drafts',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * List plans, newest first, each with its progress counted from its tasks' states. Open plans by default; state=closed lists the closed ones; channel narrows to one channel
 */
export const listPlans = <ThrowOnError extends boolean = false>(options?: Options<ListPlansData, ThrowOnError>): RequestResult<ListPlansResponses, ListPlansErrors, ThrowOnError> => (options?.client ?? client).get<ListPlansResponses, ListPlansErrors, ThrowOnError>({ url: '/api/plans', ...options });

/**
 * Make a plan in a channel: a title and a goal that groups the tasks for one piece of work. Send a key so a retry returns the same plan and writes nothing; a channel holds at most 50 open plans
 */
export const createPlan = <ThrowOnError extends boolean = false>(options: Options<CreatePlanData, ThrowOnError>): RequestResult<CreatePlanResponses, CreatePlanErrors, ThrowOnError> => (options.client ?? client).post<CreatePlanResponses, CreatePlanErrors, ThrowOnError>({
    url: '/api/plans',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Show one plan with its progress and its tasks in creation order
 */
export const getPlan = <ThrowOnError extends boolean = false>(options: Options<GetPlanData, ThrowOnError>): RequestResult<GetPlanResponses, GetPlanErrors, ThrowOnError> => (options.client ?? client).get<GetPlanResponses, GetPlanErrors, ThrowOnError>({ url: '/api/plans/{id}', ...options });

/**
 * Change a plan's title or goal; the edit is an event, and an edit that changes nothing writes nothing
 */
export const updatePlan = <ThrowOnError extends boolean = false>(options: Options<UpdatePlanData, ThrowOnError>): RequestResult<UpdatePlanResponses, UpdatePlanErrors, ThrowOnError> => (options.client ?? client).patch<UpdatePlanResponses, UpdatePlanErrors, ThrowOnError>({
    url: '/api/plans/{id}',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Close a plan: it leaves the open list and no task can join it; its tasks keep going. Safe to repeat
 */
export const closePlan = <ThrowOnError extends boolean = false>(options: Options<ClosePlanData, ThrowOnError>): RequestResult<ClosePlanResponses, ClosePlanErrors, ThrowOnError> => (options.client ?? client).post<ClosePlanResponses, ClosePlanErrors, ThrowOnError>({ url: '/api/plans/{id}/close', ...options });

/**
 * Reopen a closed plan so tasks can join it again. Safe to repeat
 */
export const reopenPlan = <ThrowOnError extends boolean = false>(options: Options<ReopenPlanData, ThrowOnError>): RequestResult<ReopenPlanResponses, ReopenPlanErrors, ThrowOnError> => (options.client ?? client).post<ReopenPlanResponses, ReopenPlanErrors, ThrowOnError>({ url: '/api/plans/{id}/reopen', ...options });

/**
 * Put a task in a plan, or take it out with plan null. The plan must be open and in the task's channel; setting the plan it already has writes nothing
 */
export const setTaskPlan = <ThrowOnError extends boolean = false>(options: Options<SetTaskPlanData, ThrowOnError>): RequestResult<SetTaskPlanResponses, SetTaskPlanErrors, ThrowOnError> => (options.client ?? client).put<SetTaskPlanResponses, SetTaskPlanErrors, ThrowOnError>({
    url: '/api/tasks/{id}/plan',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Everything a person should look at now, on one page: questions, thread questions, reviews and blocked tasks waiting on a person (oldest first), open plans with their progress, agent runs in progress with their last steps, and tasks done since 00:00 UTC
 */
export const getFocus = <ThrowOnError extends boolean = false>(options?: Options<GetFocusData, ThrowOnError>): RequestResult<GetFocusResponses, GetFocusErrors, ThrowOnError> => (options?.client ?? client).get<GetFocusResponses, GetFocusErrors, ThrowOnError>({ url: '/api/focus', ...options });

/**
 * A worker's saved sessions, most recently saved first: each one's fence, turns and size. Only that agent and people may read them; thread= keeps the sessions of one thread
 */
export const listSavedSessions = <ThrowOnError extends boolean = false>(options: Options<ListSavedSessionsData, ThrowOnError>): RequestResult<ListSavedSessionsResponses, ListSavedSessionsErrors, ThrowOnError> => (options.client ?? client).get<ListSavedSessionsResponses, ListSavedSessionsErrors, ThrowOnError>({ url: '/api/agents/{name}/sessions', ...options });

/**
 * One saved session with every chunk in turn order: the list a restore reads. A chunk uploaded but never added here is ignored
 */
export const getSavedSession = <ThrowOnError extends boolean = false>(options: Options<GetSavedSessionData, ThrowOnError>): RequestResult<GetSavedSessionResponses, GetSavedSessionErrors, ThrowOnError> => (options.client ?? client).get<GetSavedSessionResponses, GetSavedSessionErrors, ThrowOnError>({ url: '/api/agents/{name}/sessions/{session}', ...options });

/**
 * Start or restore a session before saving to it; only the agent itself. With a claim it is fenced by that claim's epoch; without one the session epoch goes up by one, so an older worker's saves are refused. Returns the chunks to restore
 */
export const openSavedSession = <ThrowOnError extends boolean = false>(options: Options<OpenSavedSessionData, ThrowOnError>): RequestResult<OpenSavedSessionResponses, OpenSavedSessionErrors, ThrowOnError> => (options.client ?? client).post<OpenSavedSessionResponses, OpenSavedSessionErrors, ThrowOnError>({
    url: '/api/agents/{name}/sessions/{session}/open',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Save one turn's new steps as a chunk; only the agent itself, under the session's current fence (a stale fence is refused). Sending the same chunk again changes nothing; other content for a saved turn is refused
 */
export const saveSessionChunk = <ThrowOnError extends boolean = false>(options: Options<SaveSessionChunkData, ThrowOnError>): RequestResult<SaveSessionChunkResponses, SaveSessionChunkErrors, ThrowOnError> => (options.client ?? client).post<SaveSessionChunkResponses, SaveSessionChunkErrors, ThrowOnError>({
    url: '/api/agents/{name}/sessions/{session}/chunks',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * One saved chunk, base64, as the pointer lists it; only that agent and people may read it
 */
export const readSessionChunk = <ThrowOnError extends boolean = false>(options: Options<ReadSessionChunkData, ThrowOnError>): RequestResult<ReadSessionChunkResponses, ReadSessionChunkErrors, ThrowOnError> => (options.client ?? client).get<ReadSessionChunkResponses, ReadSessionChunkErrors, ThrowOnError>({ url: '/api/agents/{name}/sessions/{session}/chunks/{turn}', ...options });

/**
 * Email a one-time sign-in link to a person on the board's list. Any other address gets the same answer and no email
 */
export const requestSignInLink = <ThrowOnError extends boolean = false>(options: Options<RequestSignInLinkData, ThrowOnError>): RequestResult<RequestSignInLinkResponses, RequestSignInLinkErrors, ThrowOnError> => (options.client ?? client).post<RequestSignInLinkResponses, RequestSignInLinkErrors, ThrowOnError>({
    url: '/api/auth/sign-in/magic-link',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * End this browser's session; safe to repeat
 */
export const signOut = <ThrowOnError extends boolean = false>(options?: Options<SignOutData, ThrowOnError>): RequestResult<SignOutResponses, SignOutErrors, ThrowOnError> => (options?.client ?? client).post<SignOutResponses, SignOutErrors, ThrowOnError>({ url: '/api/auth/sign-out', ...options });
